87	async function loadCandidates(): Promise<Candidate[]> {
88	  const copilotRaw = JSON.parse(await readFile(path.join("data", "copilot", "models-pricing.json"), "utf8"));
89	  const opencodeRaw = JSON.parse(await readFile(path.join("data", "opencode-go", "models-pricing.json"), "utf8"));
90	
91	  const copilotRows = dedupeCheapest(
92	    copilotRaw.models.map((m: { model: string; price1mInput: number; price1mOutput: number }) => ({
93	      model: m.model,
94	      priceInput: m.price1mInput,
95	      priceOutput: m.price1mOutput,
96	    })),
97	  );
98	  const opencodeRows = dedupeCheapest(
99	    opencodeRaw.models.map((m: { model: string; priceInput: number; priceOutput: number }) => ({
100	      model: m.model,
101	      priceInput: m.priceInput,
102	      priceOutput: m.priceOutput,
103	    })),
104	  );
105	
106	  return [
107	    ...copilotRows.map((r) => ({ provider: "copilot" as const, model: r.model, priceInput: r.priceInput, priceOutput: r.priceOutput })),
108	    ...opencodeRows.map((r) => ({ provider: "opencode-go" as const, model: r.model, priceInput: r.priceInput, priceOutput: r.priceOutput })),
109	  ];
110	}
111	
112	function normalize(value: number, min: number, max: number): number {
113	  if (max === min) return 1;
114	  return (value - min) / (max - min);
115	}
