117	async function main() {
118	  const config = JSON.parse(await readFile(path.join("config", "categories.json"), "utf8"));
119	  const blacklist: BlacklistEntry[] = JSON.parse(await readFile(path.join("config", "blacklist.json"), "utf8"));
120	  const allCandidates = await loadCandidates();
121	
122	  const candidates = allCandidates.filter((c) => {
123	    const hit = blacklist.find((b) => c.model.toLowerCase().includes(b.match.toLowerCase()));
124	    if (hit) {
125	      console.warn(`Blacklisted ${c.provider}/${c.model}: ${hit.reason}`);
126	      return false;
127	    }
128	    return true;
129	  });
130	
131	  const mapping: MappingEntry[] = JSON.parse(await readFile(path.join("data", "model-mapping.json"), "utf8"));
132	  const aaData = JSON.parse(await readFile(path.join("data", "artificial-analysis", "language-models.json"), "utf8"));
133	  const aaBySlug = new Map<string, AaModel>((aaData.models as AaModel[]).map((m) => [m.slug, m]));
134	
135	  const enriched: {
136	    provider: Provider;
137	    model: string;
138	    aaSlug: string;
139	    agenticIndex: number;
140	    codingIndex: number;
141	    intelligenceIndex: number;
142	    speed: number;
143	    blendedPrice1m: number;
144	  }[] = [];
145	
146	  for (const candidate of candidates) {
147	    const map = mapping.find((m) => m.provider === candidate.provider && m.providerModel === candidate.model);
148	    if (!map || !map.aaSlug) {
149	      console.warn(`Skipping ${candidate.provider}/${candidate.model}: no Artificial Analysis mapping.`);
150	      continue;
151	    }
152	    const aa = aaBySlug.get(map.aaSlug);
153	    if (!aa) {
154	      console.warn(`Skipping ${candidate.provider}/${candidate.model}: aaSlug "${map.aaSlug}" not found in fetched data.`);
155	      continue;
156	    }
157	    const { artificial_analysis_agentic_index, artificial_analysis_coding_index, artificial_analysis_intelligence_index } = aa.evaluations;
158	    const speed = aa.performance?.median_output_tokens_per_second;
159	    if (
160	      artificial_analysis_agentic_index == null ||
161	      artificial_analysis_coding_index == null ||
162	      artificial_analysis_intelligence_index == null ||
163	      speed == null
164	    ) {
165	      console.warn(`Skipping ${candidate.provider}/${candidate.model}: incomplete benchmark data for "${map.aaSlug}".`);
166	      continue;
167	    }
168	
169	    enriched.push({
170	      provider: candidate.provider,
171	      model: candidate.model,
172	      aaSlug: map.aaSlug,
173	      agenticIndex: artificial_analysis_agentic_index,
174	      codingIndex: artificial_analysis_coding_index,
175	      intelligenceIndex: artificial_analysis_intelligence_index,
176	      speed,
177	      blendedPrice1m: blendedPrice(candidate.priceInput, candidate.priceOutput),
178	    });
179	  }
180	
181	  const categories: Record<string, Record<Provider, ScoredCandidate[]>> = {};
182	
183	  for (const [categoryName, categoryConfig] of Object.entries(config.categories) as [string, { weights: CategoryWeights }][]) {
184	    const weights = categoryConfig.weights;
185	    if (enriched.length === 0) {
186	      categories[categoryName] = { copilot: [], "opencode-go": [] };
187	      continue;
188	    }
189	
190	    const costEfficiencies = enriched.map((e) => 1 / e.blendedPrice1m);
191	    const ranges = {
192	      agenticIndex: [Math.min(...enriched.map((e) => e.agenticIndex)), Math.max(...enriched.map((e) => e.agenticIndex))],
193	      codingIndex: [Math.min(...enriched.map((e) => e.codingIndex)), Math.max(...enriched.map((e) => e.codingIndex))],
194	      intelligenceIndex: [Math.min(...enriched.map((e) => e.intelligenceIndex)), Math.max(...enriched.map((e) => e.intelligenceIndex))],
195	      speed: [Math.min(...enriched.map((e) => e.speed)), Math.max(...enriched.map((e) => e.speed))],
196	      costEfficiency: [Math.min(...costEfficiencies), Math.max(...costEfficiencies)],
197	    };
198	
199	    const scored: ScoredCandidate[] = enriched.map((e, i) => {
200	      const normAgentic = normalize(e.agenticIndex, ranges.agenticIndex[0], ranges.agenticIndex[1]);
201	      const normCoding = normalize(e.codingIndex, ranges.codingIndex[0], ranges.codingIndex[1]);
202	      const normIntelligence = normalize(e.intelligenceIndex, ranges.intelligenceIndex[0], ranges.intelligenceIndex[1]);
203	      const normSpeed = normalize(e.speed, ranges.speed[0], ranges.speed[1]);
204	      const normCost = normalize(costEfficiencies[i], ranges.costEfficiency[0], ranges.costEfficiency[1]);
205	
206	      const score =
207	        (weights.agenticIndex ?? 0) * normAgentic +
208	        (weights.codingIndex ?? 0) * normCoding +
209	        (weights.intelligenceIndex ?? 0) * normIntelligence +
210	        (weights.costEfficiency ?? 0) * normCost +
211	        (weights.speed ?? 0) * normSpeed;
212	
213	      return {
214	        provider: e.provider,
215	        model: e.model,
216	        aaSlug: e.aaSlug,
217	        score: Math.round(score * 1000) / 1000,
218	        breakdown: {
219	          agenticIndex: e.agenticIndex,
220	          codingIndex: e.codingIndex,
221	          intelligenceIndex: e.intelligenceIndex,
222	          speed: e.speed,
223	          costEfficiency: Math.round(costEfficiencies[i] * 1000) / 1000,
224	        },
225	        priceBlendedPer1M: Math.round(e.blendedPrice1m * 1000) / 1000,
226	      };
227	    });
228	
229	    scored.sort((a, b) => b.score - a.score);
230	
231	    categories[categoryName] = {
232	      copilot: scored.filter((s) => s.provider === "copilot").slice(0, config.topNPerProvider),
233	      "opencode-go": scored.filter((s) => s.provider === "opencode-go").slice(0, config.topNPerProvider),
234	    };
235	  }
236	
237	  const outFile = path.join("data", "recommendations.json");
238	  await mkdir(path.dirname(outFile), { recursive: true });
239	  await writeFile(
240	    outFile,
241	    JSON.stringify(
242	      {
243	        generatedAt: new Date().toISOString(),
244	        topNPerProvider: config.topNPerProvider,
245	        candidatesConsidered: enriched.length,
246	        categories,
247	      },
248	      null,
249	      2,
250	    ),
251	  );
252	
253	  console.log(`Wrote recommendations for ${Object.keys(categories).length} categories (${enriched.length} scored candidates) to ${outFile}`);
254	}
255	
256	main().catch((err) => {
257	  console.error(err);
258	  process.exit(1);
259	});
